import{_ as l,o as t,c as a,ae as i}from"./chunks/framework.Dh1jimFm.js";const g=JSON.parse('{"title":"Spellcheck","description":"","frontmatter":{},"headers":[],"relativePath":"qa/spellcheck.md","filePath":"qa/spellcheck.md"}'),o={name:"qa/spellcheck.md"};function r(n,e,s,c,d,h){return t(),a("div",null,e[0]||(e[0]=[i('<h1 id="spellcheck" tabindex="-1">Spellcheck <a class="header-anchor" href="#spellcheck" aria-label="Permalink to &quot;Spellcheck&quot;">​</a></h1><p>Supervertaler includes a powerful spellcheck system that highlights misspellings while you translate, with support for regional language variants.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>Supervertaler uses a <strong>three-tier spellcheck system</strong> that automatically selects the best available backend:</p><table tabindex="0"><thead><tr><th>Backend</th><th>Description</th><th>Languages</th></tr></thead><tbody><tr><td><strong>Hunspell (cyhunspell)</strong></td><td>Native C library, best accuracy</td><td>Any language with .dic/.aff files</td></tr><tr><td><strong>Spylls</strong></td><td>Pure Python Hunspell (recommended for Windows)</td><td>Bundled: EN, RU, SV + any .dic/.aff files you add</td></tr><tr><td><strong>pyspellchecker</strong></td><td>Built-in fallback</td><td>EN, NL, DE, FR, ES, PT, IT, RU</td></tr></tbody></table><p>The system automatically falls back through backends: Hunspell → Spylls → pyspellchecker.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Windows Users:</strong> Spylls is automatically used since cyhunspell doesn&#39;t compile on Python 3.12+. This works great and supports regional variants!</p></div><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Red wavy underlines</strong> for misspelled words in the translation grid</li><li><strong>Right-click context menu</strong> with spelling suggestions</li><li><strong>Add to Dictionary</strong> — Save a word permanently</li><li><strong>Ignore</strong> — Skip a word for the current session only</li><li><strong>Regional variants</strong> — Distinguish between en_US &quot;color&quot; and en_GB &quot;colour&quot;</li></ul><h2 id="language-variants" tabindex="-1">Language Variants <a class="header-anchor" href="#language-variants" aria-label="Permalink to &quot;Language Variants&quot;">​</a></h2><p>Supervertaler supports regional language variants. The spellcheck dropdown shows variants like:</p><ul><li>English (US), English (GB), English (AU), English (CA), English (ZA)</li><li>Portuguese (PT), Portuguese (BR)</li><li>Spanish (ES), Spanish (MX), Spanish (AR)</li><li>French (FR), French (CA), French (BE)</li><li>German (DE), German (AT), German (CH)</li><li>Dutch (NL), Dutch (BE)</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Regional spelling works correctly!</strong></p><ul><li>With <strong>English (GB)</strong>: &quot;colour&quot; ✅ correct, &quot;color&quot; ❌ incorrect</li><li>With <strong>English (US)</strong>: &quot;colour&quot; ❌ incorrect, &quot;color&quot; ✅ correct</li></ul></div><h2 id="spellcheck-info-dialog" tabindex="-1">Spellcheck Info Dialog <a class="header-anchor" href="#spellcheck-info-dialog" aria-label="Permalink to &quot;Spellcheck Info Dialog&quot;">​</a></h2><p>Access detailed information about your spellcheck setup:</p><ol><li>Click the <strong>🔤 Spellcheck</strong> button in the grid toolbar</li><li>Or go to <strong>View → Spellcheck Info</strong></li></ol><p>The dialog shows:</p><ul><li>Current language and backend</li><li>Available languages</li><li>Diagnostic information (which backends are available/initialized)</li><li>Links to download additional dictionaries</li><li>Custom dictionary word count</li></ul><h2 id="adding-more-dictionaries" tabindex="-1">Adding More Dictionaries <a class="header-anchor" href="#adding-more-dictionaries" aria-label="Permalink to &quot;Adding More Dictionaries&quot;">​</a></h2><p>To add spellcheck support for additional languages or variants:</p><ol><li><p><strong>Download Hunspell dictionaries</strong> (.dic and .aff files) from:</p><ul><li><a href="https://hunspell.memoq.com/" target="_blank" rel="noreferrer">hunspell.memoq.com</a> — 70+ languages</li><li><a href="https://github.com/wooorm/dictionaries/tree/main/dictionaries" target="_blank" rel="noreferrer">GitHub: wooorm/dictionaries</a> — 92+ languages</li><li><a href="https://extensions.libreoffice.org/?Tags%5B%5D=50" target="_blank" rel="noreferrer">LibreOffice Extensions</a> — Rename .oxt to .zip</li></ul></li><li><p><strong>Extract the files</strong> — You need both <code>.dic</code> and <code>.aff</code> files (e.g., <code>nl_NL.dic</code> and <code>nl_NL.aff</code>)</p></li><li><p><strong>Place them in the dictionaries folder:</strong></p><ul><li>Open Supervertaler</li><li>Go to Spellcheck Info dialog</li><li>Click &quot;📁 Open Dictionaries Folder&quot;</li><li>Copy your .dic and .aff files there</li><li>You can also organize in subfolders (e.g., <code>dictionaries/en/en_GB.dic</code>)</li></ul></li><li><p><strong>Restart Supervertaler</strong> — The new language will appear in the dropdown</p></li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Spylls bundled dictionaries</strong> (EN, RU, SV) are stored inside the spylls pip package, not in your dictionaries folder. Add your own .dic/.aff files to the dictionaries folder to extend available languages.</p></div><h2 id="custom-dictionary" tabindex="-1">Custom Dictionary <a class="header-anchor" href="#custom-dictionary" aria-label="Permalink to &quot;Custom Dictionary&quot;">​</a></h2><p>You can add words that Supervertaler should always accept:</p><ul><li><strong>Right-click a &quot;misspelled&quot; word</strong> → <strong>Add to Dictionary</strong></li><li>Or manually edit <code>user_data/dictionaries/custom_words.txt</code></li></ul><p>Custom words are stored permanently and apply to all languages.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="spellcheck-not-working" tabindex="-1">Spellcheck not working? <a class="header-anchor" href="#spellcheck-not-working" aria-label="Permalink to &quot;Spellcheck not working?&quot;">​</a></h3><ol><li><strong>Check the language</strong> — Make sure the correct language variant is selected</li><li><strong>Check the backend</strong> — Open Spellcheck Info to see which backend is active</li><li><strong>Missing dictionaries</strong> — Some languages require manual dictionary installation</li></ol><h3 id="wrong-language-variant" tabindex="-1">Wrong language variant? <a class="header-anchor" href="#wrong-language-variant" aria-label="Permalink to &quot;Wrong language variant?&quot;">​</a></h3><p>If you need British English but only have US English:</p><ol><li>Download <code>en_GB.dic</code> and <code>en_GB.aff</code> from one of the dictionary sources</li><li>Place them in your dictionaries folder</li><li>Select &quot;English (GB)&quot; from the dropdown</li></ol><h3 id="linux-crashes" tabindex="-1">Linux crashes? <a class="header-anchor" href="#linux-crashes" aria-label="Permalink to &quot;Linux crashes?&quot;">​</a></h3><p>On Linux, some Hunspell configurations can cause crashes. Try:</p><ul><li>Installing proper Hunspell dictionaries: <code>sudo apt install hunspell-&lt;lang&gt;</code> (e.g., <code>hunspell-pl</code> for Polish)</li><li>Temporarily disabling spellcheck in Settings → View Settings</li><li>See <a href="./../troubleshooting/linux.html">Linux-Specific Issues</a> for more details</li></ul><h2 id="technical-details" tabindex="-1">Technical Details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical Details&quot;">​</a></h2><p>For developers and advanced users:</p><table tabindex="0"><thead><tr><th>Project</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://github.com/barrust/pyspellchecker" target="_blank" rel="noreferrer">pyspellchecker</a></td><td>Built-in word frequency spellcheck</td></tr><tr><td><a href="https://github.com/zverok/spylls" target="_blank" rel="noreferrer">spylls</a></td><td>Pure Python Hunspell implementation</td></tr><tr><td><a href="http://hunspell.github.io/" target="_blank" rel="noreferrer">Hunspell</a></td><td>Original C/C++ spellcheck library</td></tr></tbody></table><p>The spellcheck manager is located in <code>modules/spellcheck_manager.py</code> and provides:</p><ul><li>Automatic backend selection</li><li>Dictionary file detection (including subdirectories)</li><li>Word caching for performance</li><li>Custom dictionary management</li></ul>',40)]))}const p=l(o,[["render",r]]);export{g as __pageData,p as default};
